from dental_release.paths import expand as _release_expand
from pathlib import Path
import datetime, json, shutil
from freeze import ROOT, sha, dump

def main():
    r1 = json.loads((ROOT / 'raw/RESULTS_R1.json').read_text())
    r2 = json.loads((ROOT / 'raw/RESULTS_R2.json').read_text())
    fp = json.loads((ROOT / 'FROZEN_PREDICTIONS.json').read_text())
    src = json.loads((ROOT / 'SOURCE_MANIFEST.json').read_text())
    fe = json.loads((ROOT / 'raw/L005_lo_M1_k6_thin_printed_resin_fe.json').read_text())
    delta = []
    for name in ('axial', 'offaxis30'):
        c = fe['cases'][name]
        full = c['s1_surface_max_per_N']
        remote = c['s1_surface_max_outside_zone_per_N']
        strength = 80.5
        delta.append({'loadcase': name, 'full_to_remote_peak_ratio': full / remote, 'original_remote_proxy_at16min_N': strength / remote, 'full_surface_proxy_at16min_N': strength / full, 'original_remote_screen_at150N': strength >= 150 * remote, 'full_surface_screen_at150N': strength >= 150 * full, 'resolution_level': 'PER_SURFACE_REGION', 'time_scale': 'SIMULTANEOUS', 'interpretation': 'Difference in retained failure-mode region, not measured crown strength. A contact damage closure is UNKNOWN.'})
    dump(ROOT / 'raw/OPERATION_DELTA.json', delta)
    reasons = {'TM01': 'Already built in LANE_X14_SINTER_POSITION. No duplicated sintering-distortion construction.', 'TM02': 'Selected partial chain: local source provides furnace/time/thickness-conditioned optics, not profile-conditioned strength or shrinkage.', 'TM03': 'Verified primary abstract online, but no quantitative local protocol table/toolpath/wear calibration located. Deferred, not inferred from milling time.', 'TM04': 'No paired local flaw-depth/profile and regional flexural/fractography calibration identified for D1.', 'TM05': 'Selected partial chain: local cure-conditioned strength assay and inherited same-resin D1 FE; cytotoxicity/warp/part cure gradient not identified.', 'TM06': 'D1 resin anisotropic elastic tensor and matched orientation-specific accuracy/strength data absent. Existing staircase geometry cannot supply it.', 'TM07': 'No measured machine-specific plate-error map or QC coupons.', 'TM08': 'No local specimen-linked NIST XCT/fracture-location pair selected; external specimen field cannot be mapped to the same D1 tooth without a new chain.', 'TM09': 'No local matched as-built ostut CT /compression data; nominal FE slope is not manufactured modulus reference .', 'TM10': 'No matched patient clasp geometry plus retention/cycle series on this D1 fixed-crown model. A separate removable model would be required.', 'TM11': 'No local LCM process/defect/Weibull series for D1; table means do not assign an ISO class.', 'TM12': 'Population scanner RMS does not identify D1 directional registration error. No paired reference scan or local drift field.', 'TM13': 'No manufactured/cemented D1 micro-CT volume.', 'TM14': 'No dated machine QC time series; synthetic drift would only validate arithmetic.', 'TM15': 'No measured adjustment/remake time or local cost schedule for D1.', 'TM16': 'Credibility report is not a new manufacturing/material capability and does not replace the absent physical assays.', 'TM17': 'No real batch/production chain. Traceability template cannot decide D1 optical or mechanical response.', 'TM18': 'No actual automated three-unit bridge geometries on this patient model; original pilot endpoint is not one-crown physics.', 'TM19': 'No local laboratory order/resource log for predictive throughput validation.', 'TM20': 'No matched same-model implant/route fatigue series; polished bars cannot validate D1 or threaded as-built surface.'}
    selection = {'selected': ['TM02', 'TM05'], 'considered': 20, 'not_selected': 18, 'attrition_fraction': 0.9, 'scope': 'Directed local source/code availability plus same-D1 requirement; not a proof of global absence', 'all_candidates': [{'id': k, 'selected': k in ('TM02', 'TM05'), 'reason': v} for (k, v) in reasons.items()], 'prior_work': [_release_expand('X14'), 'LANE_X1_CROWN_LOOP', 'PROOF_LANE_INFOLINK4 L10/L11'], 'search_record': 'COMMANDS.md; notes/NORTHSTAR_SPEC.md; OLD_DENTAL_CELL_INDEX.md/jsonl; targeted Sol/proof_lane/The swarm/BodyTwin result searches'}
    dump(ROOT / 'SELECTION.json', selection)
    result = {'lane': 'X64-manufacturing', 'claim_type': 'capability', 'status': 'CONDITIONAL_CAPABILITY_WITH_PHYSICAL_VALIDATION_UNKNOWN', 'what_became_possible': 'Two spatial manufacturing queries on one published patient model and frozen matched measurement targets; local support/inverse demand made explicit', 'chains': [{'id': 'TM02', 'full_chain_status': 'PARTIAL_CONDITIONAL', 'implemented': 'furnace procedure/time + measured optical rows → crown ray field → source-support/interval query → matched TP sites', 'missing': 'Strength, sinter distortion and curved optical transfer validation', 'resolution_level': 'PER_POINT geometric prediction, PHENOMENOLOGICAL optical disclosure, POPULATION reference', 'time_scale': 'HANDOVER'}, {'id': 'TM05', 'full_chain_status': 'PARTIAL_CONDITIONAL', 'implemented': 'cure-specific measured strength → D1 tensile demand field → fixed-load screen → inverse matched fracture assay', 'missing': 'Part-specific modulus/contact/cure gradients, cytotoxicity and warp', 'resolution_level': 'PER_SURFACE_REGION stress query, POPULATION strength reference', 'time_scale': 'HANDOVER'}], 'same_patient_model': {'id': 'STS L005_lo_M1_k6 D1 thin', 'crown_sha256': src['crown']['sha256'], 'source': 'X1 D1 derived CC BY4.0 STS anatomy'}, 'R1': r1, 'R2': r2, 'operation_delta': delta, 'selection': selection, 'external_referent': r2['external_referent'], 'external_validation_scope': 'Independent reference for published coupon population TP /flexural strength only. No independent measured D1 crown endpoint. Source reuse is not held-out validation.', 'external_referent_refutation_scope': 'Published values refute a thickness-independent TP or cure-independent strength constant; synthetic rearrangements separately refute sufficiency under the stated model.', 'phenomenological_debts': [{'closure': 'normal material chord → flat coupon TP', 'replacement_measurement': 'Location-tagged matched curved D1 TP map, same batch/sinter/aging/background'}, {'closure': 'E=2100 MPa, nu=0.35 transferred to every cure', 'replacement_measurement': 'Matched cure-specific modulus and contact/force-displacement traces'}, {'closure': 'bar flexural mean → local crown strength', 'replacement_measurement': 'D1 fracture load and origin in both frozen loadcases, separate held-out replicates'}, {'closure': '+/-0.12mm geometry scenario', 'replacement_measurement': 'Registered as-built scan with per-site uncertainty and metrology traceability'}], 'numerics': 'Outward arithmetic enclosure for declared surrogate boxes; rigorous continuum mesh/FE and physical constitutive enclosures absent. No linear physical sensitivity claim.', 'attrition': {'chain_candidates': selection, 'R1_optical': {'visible_considered': 236, 'outside_0_5_to1mm_support': 203, 'outside_fraction': 203 / 236}, 'R2_optical': {'visible_considered': 236, 'outside_entire_scenario_support': 229, 'outside_fraction': 229 / 236, 'retained': 7, 'reason': 'Whole ray scenario interval outside measured knot support; no dropped ray silently assigned a value'}, 'source_rows': {'considered': 8, 'kept': 8, 'rejected': 0, 'unresolved_protocol_conflicts': 'Optics black/white labeling/formula anomalous; resin printer/aging ambiguity retained'}}, 'cost': {'R1_measured': r1['cost'], 'R2_measured': r2['cost'], 'figure': json.loads((ROOT / 'raw/FIGURE_COST.json').read_text()), 'successful_end_to_end_commands': json.loads((ROOT / 'VERIFICATION.json').read_text())['commands'], 'inherited_and_preparation': 'Inherited single geometry/FE timings retained; prior data acquisition, search/reasoning and full campaign cost UNMEASURED. No full-cost gain claim.'}, 'graph_targets': ['DENT-MAT-TRANSLUCENCY', 'DENT-MAT-RESTORATIVE-PSP'], 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'FROZEN_PREDICTIONS_sha256': sha(ROOT / 'FROZEN_PREDICTIONS.json'), 'large_arrays_created': [], 'read_only_array_inputs': {k: v for (k, v) in src.items() if k in ('model', 'stress')}, 'artifacts': {str(p.relative_to(ROOT)): {'sha256': sha(p), 'bytes': p.stat().st_size} for p in [ROOT / 'raw/RESULTS_R1.json', ROOT / 'raw/RESULTS_R2.json', ROOT / 'raw/OPTICAL_RAYS.npz', ROOT / 'raw/SUFFICIENCY_STATES.npz', ROOT / 'raw/DEMANDS.npz', ROOT / 'raw/OPTICAL_INTERVALS.json', ROOT / 'FROZEN_PREDICTIONS.json', ROOT / 'manufacturing_demo.png', ROOT / 'manufacturing_demo.pdf']}, 'next_construction': 'Matched part measurements first. A location-tagged optical map or fracture/contact trace can replace specific closures. Do not run another bulk-mean adapter.'}
    dump(ROOT / 'results.json', result)
    (ROOT / 'README_DEMO.md').write_text("# Two manufacturing issues on the same D1 - crown\n\nRun `./run_all.sh` in this catalogue. It recalculates both chains offline, tests controls and error injections, compares with preserved outcomes and creates the figure. No new FE solution or GPU is required. Execution takes approximately 2,5 s here; frozen original results and predictions are preserved.\n\nThe idea is to use the process measurements where the crown needs them: optical path on visible surface and strength at local tensile voltage. Both chains use the same STS D1 - crown , L005 lower molar k 6 . They are two material/process options, not a common zirconia/resin material. This gives the choice of **labprototype and the next measurement**, with physical kronvalidation **UNKNOWN**.\n\n| Question | Executable result | Resolution and reference |\n|---|---|---|\n| TM02 : can fast sintering keep the optics? | The article's bike is 105 against 420 min. Only 33/236 exposed normal beams have length within 0,5 – 1,0 mm . With the declared ± 0,12 mm geometry scenario left 7 : default 5 model pass and 2 uncertain, fast 7 uncertain. Hel crown UNKNOWN . | PER_POINT geometry , PHENOMENOLOGICAL optics; published POPULATION - TP in [Albayrak & Eraslan, Table 2 – 3 ](https://doi.org/10.4103/jips.jips_345_22). |\n| TM05 : shortest post curing for the fixed load? | Under the axial 150 N load, 16 minutes passes the declared mean +/- 2SD box. With 30° the 16 and 60 min become unsafe, 32 min fails . | PER_SURFACE_REGION calculated towing voltage; POPULATION-styrka i [Siqueira m.fl., table 1](https://doi.org/10.3390/ma17071496). |\n| Is the same material and histogram enough? | Identity error precisely 0; spatial relocation visibly changes the minimum with 4,77 TP and local strength/ stress with 0,482929, so both decisions can be reversed. | PER_POINT synthetic counter-examples of real D1 modes. These are not experimental reference. |\n\n[Creating manufacturing issues](manufacturing_demo.png)\n\nWhat does not holds : a full TM02 strength/shrunk chain or a full TM05 conversion/cytotoxicity/warp chain. Published discs and test rods do not validate this crown . TP is a color difference to black/white background; normal material cord is an untested transfer to curved crown, not measured light path. Boundary TP ≥ 12 and 150 N load are frozen research scenarios. ± 0,12 mm and means ± 2 SD are model scenarios, no rigid anatomical error limits or statistical prediction intervals. Interval arithmetic encloses the declared model; FE and continuum errors lack rigorous enclosure.\n\nThe existing X1 proxy omitted the contact zone. When its actual voltage field is maintained there, the power proxy of the oblique load becomes approximately 30,1 times lower. This shows that the region of malice must comply with the decision. Which proxy describes real breakage requires contact/crack mechanics and a matched test. The impact of the hardening on module and contact is not measured; all recipe reuses E=2100 MPa and now= 0,35 as cloak.\n\n`FROZEN_PREDICTIONS.json` has a time stamp and hash before future lab measurements. `MEASUREMENT_REQUEST.json` indicates precise optical points and four different mechanical conditions: 16 / 60 min × axial/sdown load. Four relationships are not four specimen that validates reliability. Without spatial law, all 236 exposed test points are needed for the optical query ; a single worst position is sufficient only during an untested homogeneous, monotonous model. `exports/D1_crown.stl` is existing end geometry in mm , no CAM pathways or validated manufacturing parameters.\n\nThe controls have the same sources and geometry. Source tables, two independent voltage calculations and two beam-triangle calculations are consistent within frozen gates; injected errors are rejected. This is numerical verification. No methodological advantage, clinical safety or improved total cost is claimed.\n\nLicenses: STS - Tooth3D , Wang etc., [dataset 10.5281/zenodo.10597292 ](https://doi.org/10.5281/zenodo.10597292), CC BY 4.0 , via existing X1 - derivation . [Optics article](https://pmc.ncbi.nlm.nih.gov/articles/PMC10088447/) is CC BY-NC-SA 4.0 ; its basis is for research without commercial use under the license. [Resin article](https://doi.org/10.3390/ma17071496) is CC BY 4.0 . No second patient data sets, identifying personal data or new dataset downloads are used. Local original routes, attribute and SHA256 are available in SOURCE_MANIFEST.json. Status PENDING_INDEPENDENT_REVIEW.\n")
    (ROOT / 'RESULTS.md').write_text("# D1: process data at the area where the decision is decided\n\nTwo partial manufacturing chains are run on the same STS - crown : sintering → thickness-bound optics and post curing → local mechanical demand. The new is the spatial consumer and the inverse question of measurement; Astra4 already had the source tables and X1 geometry/voltage fields. Externally reference is [optics published TP-table](https://doi.org/10.4103/jips.jips_345_22) and [resinens bend strength table](https://doi.org/10.3390/ma17071496). No independently manufactured D1 - crown is available as a physics facit. `claim_type=capability` .\n\nR1 : 33 / 236 visible normal beams are in the article's 0,5 – 1,0 mm range, loss 86,02 %. Fast sintering passes the nominal TP ≥ 12 scenario at 27 of these 33; standard at 33 of 33 . The 203 others get UNKNOWN . R2 : the entire declared ± 0,12 mm-Length Box with the source's dimensional tolerance has support at 7/236 , loss 97,03 %. Standard gets 5 model pass, fast 0 ; no full crown decision may pass. This is PHENOMENOLOGICAL optics on PER_POINT geometry, not measured crowns - TP.\n\nResin at declared 150 N-last: axial top 17,198802 MPa and oblique top 82,827918 MPa , PER_SURFACE_REGION from local facet pansorer. With mean values, 16 and 60 min are selected respectively. When the same source is held as the mean ± 2 SD-box passes the 16 min axial question, while the oblique load 16 and 60 min are unsafe and 32 min fails . No statistical coverage is assigned to these boxes. The source of material is POPULATION ; physical patient strength and protocol-specific module is UNKNOWN .\n\nSufficiency was tested before final use of the summaries. Both counters have the same means and entire histogram to exact machine identity: error 0 mm and 0 MPa respectively, even the canonic mean TP identity has the wrong 0. Visibly minimum difference 4,770000 TP , strength/tow voltage-minimum divides 0,482928954 ; decision is reversed. Minimum extension for the fixed optics issue is minimum over visible surface; for mechanics minimum of local coupled S_i / sigma_i per load case . When the direction of vision or load changes, the spatial connection is needed again. The counter pair is its own synthetic state, not independent measurements. Raw data in `raw/SUFFICIENCY_STATES.npz` .\n\nA crucial difference in operation is the contact zone. X1 : s temporary resinproxy for 16 min sloping load was 4393,55 N when the zone was excluded. The whole surface's frozen tensor field provides in the same average strength screen about 145,78 N. The ratio 30,14 refers to the selected region and error, no measured strength change. The fact that average strength alone validates any of these breaking measures is not proven. `raw/OPERATION_DELTA.json` preserves both. The next mechanical test must report the source of crime and contact/force-displacement; a larger material summary does not solve query .\n\nR2 changes the operation from the scaler acceptance to the outward-rounded enclosure of the declared optical model and inverse measurement requirements. The monotonicity of the source support provides corner-extrema; mpmath range at 30 decimals envelops each corner. All separate corner and interior probes are within these boxes; injected too tight bounds is rejected. This does not contain any unknown optics, geometry or FE-rest. No affinity physical sensitivity is reported as safe.\n\nControl line: source value error 0 ; max radiation difference 8,88e-16 mm ; max independent voltage difference 2,41e-8 MPa / N ; each declared fault injection is rejected. Rerecording accurately reproduces all scientific outcomes and leaves frozen predictions unchanged. No algorithm gains are claimed.\n\nRun `./run_all.sh` . README_DEMO has figure, idea/result / restrictions and licenses. Precise run commands and failures are found in COMMANDS.md and runes/*/ commands.json. R1 took 0,55 s and top RSS 325 MiB; R2 0,068 s and 109 MiB before figure. Supplementary rerun , inheritance from geometry / FE and source search is posted in results.json . Preparation and the entire previous campaign are not time-measured; no total cost advantage is claimed.\n\n18 / 20 chain candidates were removed from this narrowed search. SELECTION.json indicates any missing data link or previous design. Original TM03 intent was abandoned before PREREG because quantitative local protocol table not found; no measuring gates were changed. Preserved implementation errors: error working directory at mileage write (restored), numpy -boool at JSON serialization, and Matplotlib/ NumPy ABI (system package with -s used). None of these counts as scientific rejection.\n\nStatus PENDING_INDEPENDENT_REVIEW. Graph dispatch/feedback binds TM02 as defined consumer definition and TM05 as experiments to existing goal. Missing coverage: quantified empirical transfer from process/test material to curved D1 surface and contact breach. Source statuses and native graphs are not changed.\n")
    (ROOT / 'HANDOFF.md').write_text('X64 -manufacturing, R1 and R2 completed. Run `./run_all.sh` ; README_DEMO.md is the reader tree, raw/RESULTS_R1.json and raw/RESULTS_R2.json and preserved npz contains all numerical outcomes. FROZEN_PREDICTIONS.json must never be readjusted for measurement.\n\nCapability : the same D1 patient geometry is used for two process options with local consumers and an inverse assay request. TM02/TM05 is partial and conditional , not full physical calibration . Astra4 : s L10 / L11 and X1 are reused; no copy of the table is named as new detected. Control against exactly the same information is consistent within frozen gates.\n\nWhat failed : bulking agents and entire histograms are not sufficient; identity error 0 and downstream differences 4,77 TP and 0,482929 respectively. Only 7/236 optical points has support for the entire declared scenario ranges; 229 explicitly UNKNOWN . 16-minute resin passes axial 150 N model box; no process is decidedly biased load decision. X1 : s contact zone exception changes the same resins sloping load proxy from 4393,55 to approximately 145,78 N when the zone is kept; none of them are physically validated.\n\nSurprising/essential : more source table precision cannot solve the lack of region/fault mode. The minimum extension is query -specific local minimum, but a new load or view needs the full location connection. Optical normal beams can become corpora across the crown (up to approximately 10 mm ) and are therefore a particularly weak surrogate for flat 0,5 – 1mm samples. Keep this negative transfer, do not just change the interpolator.\n\nNext design R3 : run frozen matched measurements from MEASUREMENT_REQUEST.json . For optics: Placemarked TP -map for ST / SP on D1 , same blank and aging . For mechanics: 16 / 60 min × axial/down with contact stiffness, force displacement and crime origin. Population/replicate dimensioning is still UNKNOWN. A single worst-point test or breaking load test can only identify a conditional homogenous transfer, not a general field or clinical reliability. Missing lab: Build a new mechanistic contact/spectral operation only when its necessary inputs are available; run does not yet have a bulking agent adapter.\n\nMissing graphcoverage for review : ( 1 ) explicit empirical coupon→took optic transfer route with PER_POINT measurement port and ( 2 ) process/contact zone→ D1 offence origin with PER_SURFACE_REGION port. The process leaves material permission through HANDOVER , evaluation against the same contemporary stress/ TP is SIMULTANEOUS . No personal scientific assignments. GRAPH_FEEDBACK.json is PENDING_INDEPENDENT_REVIEW.\n')
    shutil.copyfile(ROOT / 'raw/crown.stl', ROOT / 'exports/D1_crown.stl')
    dump(ROOT / 'exports/PROTOTYPE_MANIFEST.json', {'geometry': 'D1_crown.stl', 'units': 'mm', 'sha256': sha(ROOT / 'exports/D1_crown.stl'), 'license': 'Derived STS-Tooth3D CC BY4.0 via X1, Wang et al., Zenodo10.5281/zenodo.10597292', 'process_parameters': 'Source- and batch-matched research only; no CAM toolpath, shrink compensation or validated clinical material recipe provided', 'measurement_request': '../MEASUREMENT_REQUEST.json', 'frozen_predictions_sha256': sha(ROOT / 'FROZEN_PREDICTIONS.json')})
    dump(ROOT / 'ATTEMPTS.json', [{'round': 'R1', 'hypothesis': 'Process-tagged material summaries may decide local D1 queries', 'changed_operation': 'Optical rays and retained full stress field coupled to published rows', 'outcome': 'Summaries insufficient; conditional nominal decisions and support attrition exposed', 'parent_artifacts': ['PROOF_LANE_INFOLINK4 L10/L11', 'LANE_X1_CROWN_LOOP D1'], 'next': 'R2 local interval/inverse assay'}, {'round': 'R2', 'hypothesis': 'Location-preserving model boxes can nominate smallest missing assays', 'changed_operation': 'Outward finite-box enclosure and inverse threshold preimage, prospective freeze', 'outcome': 'Axial16min model pass; snedlast and whole optics unresolved; physical UNKNOWN', 'next': 'R3 matched location/contact assay, not more means'}])
    with (ROOT / 'COMMANDS.md').open('a') as f:
        f.write(_release_expand("\nExact construction commands from lane root:\n```bash\nOPENBLAS_NUM_THREADS=4 OMP_NUM_THREADS=4 MKL_NUM_THREADS=4 python3 code/freeze.py\nOPENBLAS_NUM_THREADS=4 OMP_NUM_THREADS=4 MKL_NUM_THREADS=4 python3 code/run_r1.py > raw/R1_EXECUTION.log 2>&1\nOPENBLAS_NUM_THREADS=4 OMP_NUM_THREADS=4 MKL_NUM_THREADS=4 python3 code/freeze_r2.py\nOPENBLAS_NUM_THREADS=4 OMP_NUM_THREADS=4 MKL_NUM_THREADS=4 python3 code/run_r2.py > raw/R2_EXECUTION.log 2>&1\nchmod +x run_all.sh\n./run_all.sh\npython3 code/write_report.py\n```\nFreeze commands are historical and intentionally refuse rerun. Use `./run_all.sh` for safe repeatability. Every child argv/cwd/environment/exit/time is in runs/*/commands.json; stdout/stderr are retained. Figure uses `python3 -s` with system NumPy1.21.5/Matplotlib3.5.1. Numerical consumers use NumPy2.2.6, scipy, trimesh, rtree, lxml and mpmath. No package changed.\n\nGraph commands from `@DENTAL_INPUT_ROOT@/workspace`:\n```bash\n./graph working rank --limit 8\n./graph working packet --id DENT-MAT-TRANSLUCENCY\n./graph working packet --id DENT-MAT-RESTORATIVE-PSP\n./graph dispatch --id DENT-MAT-TRANSLUCENCY --lane LANE_X64_MANUFACTURING_TM02 --kind define --reason 'Define D1 spatial optical-ray consumer of existing L10 table with explicit coupon transfer debt and matched measurement target' --task-file results/LANE_X64_MANUFACTURING/TASK.md\n./graph dispatch --id DENT-MAT-RESTORATIVE-PSP --lane LANE_X64_MANUFACTURING_TM05 --kind experiment --reason 'D1 cure-conditioned mechanical screen with scalar sufficiency witness and inverse matched assay; reuse existing L11 without claiming table extraction as new' --task-file results/LANE_X64_MANUFACTURING/TASK.md\n```\nAll arrays are small; no job >=4GB RAM or GPU executed. Directed `du -sh .` before/after checked own storage. Model/stress arrays remain read-only at original `@DENTAL_EXTERNAL_ROOT@/storage/...` locations with source hashes. No whole zip extraction or cache copy.\n"))
    print('Reader artifacts written')
if __name__ == '__main__':
    main()
